"""cb_pandas_plotly — pandas plotting backend for CodeBench (plotly.js out).

pandas' built-in 'matplotlib' backend drives real-matplotlib internals
(set_visible, freq converters, twin axes) that the plotly-backed
matplotlib shim doesn't emulate, so ``df.plot()`` crashes. This module
implements pandas' OFFICIAL third-party-backend protocol
(``pd.options.plotting.backend = "cb_pandas_plotly"``): same user code,
``df.plot(kind=...)`` / ``series.plot()`` / ``df.hist()`` /
``df.boxplot()``, rendered through the same plotly pipeline as the
matplotlib shim and shown by ``plt.show()``.

Returns the shim Axes (mirrors the matplotlib backend's return type).
Top-level imports stay light: pandas eagerly imports this module to
validate the option, so plotly/matplotlib load lazily inside calls.
"""

import numpy as np

__all__ = ['plot', 'hist_series', 'hist_frame', 'boxplot', 'boxplot_frame',
           'boxplot_frame_groupby', 'deregister', 'register']


def _plt():
    from matplotlib import pyplot as p
    return p


def _go():
    import plotly.graph_objects as go
    return go


def _is_series(data):
    return hasattr(data, 'name') and not hasattr(data, 'columns')


def _gaussian_kde(arr, gridsize=200):
    """numpy-only gaussian KDE (Scott's rule) — self-contained so this
    backend has no dependency on the seaborn package."""
    arr = np.asarray(arr, float)
    arr = arr[np.isfinite(arr)]
    n = len(arr)
    if n < 2:
        return np.array([0.0]), np.array([0.0])
    std = arr.std(ddof=1)
    bw = std * n ** (-1.0 / 5.0) if std > 0 else 1.0
    lo, hi = arr.min() - 3 * bw, arr.max() + 3 * bw
    grid = np.linspace(lo, hi, gridsize)
    diff = (grid[:, None] - arr[None, :]) / bw
    dens = np.exp(-0.5 * diff ** 2).sum(axis=1) / (n * bw * np.sqrt(2 * np.pi))
    return grid, dens


def _numeric_cols(df):
    cols = []
    for c in df.columns:
        try:
            np.asarray(df[c], dtype=float)
            cols.append(c)
        except (TypeError, ValueError):
            pass
    return cols


def _apply_common(kwargs):
    p = _plt()
    if kwargs.get('title'):    p.title(str(kwargs['title']))
    if kwargs.get('xlabel'):   p.xlabel(str(kwargs['xlabel']))
    if kwargs.get('ylabel'):   p.ylabel(str(kwargs['ylabel']))
    if kwargs.get('logy'):     p.yscale('log')
    if kwargs.get('logx'):     p.xscale('log')
    if kwargs.get('grid'):     p.grid(True)
    return p.gca()


def _x_values(data, x, kwargs):
    if x is not None and hasattr(data, 'columns'):
        return np.asarray(data[x]), str(x)
    idx = data.index
    try:
        return np.asarray(idx), (str(idx.name) if idx.name is not None else None)
    except Exception:
        return np.arange(len(data)), None


def plot(data, kind='line', x=None, y=None, **kwargs):
    go = _go(); p = _plt()
    fig = p._ensure_fig()
    color = kwargs.get('color', kwargs.get('c'))
    alpha = kwargs.get('alpha')

    # normalize to (x_arr, [(label, values)])
    if _is_series(data):
        xs, _xl = _x_values(data, None, kwargs)
        series = [(str(data.name) if data.name is not None else '', np.asarray(data))]
    else:
        if kind == 'scatter':
            xs = np.asarray(data[x]) if x is not None else np.arange(len(data))
            ya = np.asarray(data[y]) if y is not None else None
            s = kwargs.get('s')
            p.scatter(xs, ya, s=s, c=color, alpha=alpha)
            p.xlabel(str(x) if x is not None else '')
            p.ylabel(str(y) if y is not None else '')
            return _apply_common(kwargs)
        xs, _xl = _x_values(data, x, kwargs)
        if y is not None:
            ycols = [y] if isinstance(y, str) else list(y)
        else:
            ycols = [c for c in _numeric_cols(data) if c != x]
        series = [(str(c), np.asarray(data[c])) for c in ycols]

    if kind in ('line', 'area'):
        for name, vals in series:
            tr = go.Scatter(x=p._to_list(xs), y=p._to_list(vals), mode='lines',
                            name=name, showlegend=bool(name),
                            fill=('tozeroy' if kind == 'area' else None))
            if alpha is not None: tr.opacity = float(alpha)
            fig.add_trace(tr)
    elif kind in ('bar', 'barh'):
        cats = [str(v) for v in xs]
        for name, vals in series:
            bk = dict(name=name, showlegend=bool(name))
            if color is not None: bk['marker_color'] = p._color_to_str(color)
            if alpha is not None: bk['opacity'] = float(alpha)
            if kind == 'bar':
                fig.add_trace(go.Bar(x=cats, y=p._to_list(vals), **bk))
            else:
                fig.add_trace(go.Bar(y=cats, x=p._to_list(vals), orientation='h', **bk))
        if kwargs.get('stacked'):
            try: fig.update_layout(barmode='stack')
            except Exception: pass
    elif kind == 'hist':
        bins = kwargs.get('bins', 10)
        for name, vals in series:
            hk = dict(name=name, showlegend=bool(name), opacity=0.75)
            if isinstance(bins, (int, np.integer)): hk['nbinsx'] = int(bins)
            fig.add_trace(go.Histogram(x=p._to_list(vals), **hk))
        if len(series) > 1:
            try: fig.update_layout(barmode='overlay')
            except Exception: pass
    elif kind == 'box':
        for name, vals in series:
            fig.add_trace(go.Box(y=p._to_list(vals), name=name))
    elif kind in ('kde', 'density'):
        for name, vals in series:
            gx, gy = _gaussian_kde(np.asarray(vals, float))
            fig.add_trace(go.Scatter(x=gx.tolist(), y=gy.tolist(), mode='lines',
                                     name=name, showlegend=bool(name)))
    elif kind == 'pie':
        name, vals = series[0]
        labels = [str(v) for v in (data.index if hasattr(data, 'index') else range(len(vals)))]
        fig.add_trace(go.Pie(values=p._to_list(vals), labels=labels))
    else:
        raise ValueError(f"cb_pandas_plotly: unsupported kind={kind!r}")
    return _apply_common(kwargs)


def hist_series(self, by=None, bins=10, **kwargs):
    return plot(self, kind='hist', bins=bins, **kwargs)


def hist_frame(data, column=None, bins=10, **kwargs):
    if column is not None:
        cols = [column] if isinstance(column, str) else list(column)
        data = data[cols]
    return plot(data, kind='hist', bins=bins, **kwargs)


def boxplot(data, column=None, by=None, **kwargs):
    if column is not None and hasattr(data, 'columns'):
        cols = [column] if isinstance(column, str) else list(column)
        data = data[cols]
    return plot(data, kind='box', **kwargs)


def boxplot_frame(data, column=None, by=None, **kwargs):
    return boxplot(data, column=column, by=by, **kwargs)


def boxplot_frame_groupby(grouped, **kwargs):
    p = _plt(); go = _go()
    fig = p._ensure_fig()
    for key, grp in grouped:
        for c in _numeric_cols(grp):
            fig.add_trace(go.Box(y=p._to_list(grp[c]), name=f"{key}:{c}"))
    return p.gca()


def register():   # pandas calls these on backend switch
    pass


def deregister():
    pass
